import { useEffect, useState } from 'react';
import axiosAuth from '../utils/axiosAuth'; // ✅ Make sure you're using the auth-enabled Axios

function Dashboard() {
  const [items, setItems] = useState([]);
  const userId = localStorage.getItem('userId');

  const fetchItems = async () => {
    try {
      const res = await axiosAuth.get(`/items/user`, {
        params: { userId }
      });
      setItems(res.data);
    } catch (err) {
      console.error('Dashboard error:', err.response?.data || err.message);
    }
  };

  const markResolved = async (itemId) => {
    try {
      await axiosAuth.post('/items/resolve', { itemId });
      alert('Item marked as resolved');
      fetchItems(); // ✅ Refresh after update
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchItems();
  }, [userId]);

  return (
    <div style={{ maxWidth: '600px', margin: 'auto' }}>
      <h2>Your Reported Items</h2>
      <ul>
        {items.map(item => (
          <li key={item._id}>
            <strong>{item.title}</strong> ({item.type})<br />
            {item.description}<br />
            <em>{item.location} — {new Date(item.date).toLocaleDateString()}</em><br />
            {!item.resolved && (
              <button onClick={() => markResolved(item._id)}>Mark as Resolved</button>
            )}
            {item.resolved && <span style={{ color: 'green' }}>✅ Resolved</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default Dashboard;
